import{_ as t}from"./chunks/live.DqM0EmIK.js";import{_ as a,o as s,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const g=JSON.parse('{"title":"Live: the active map","description":"","frontmatter":{"pageId":"players/live","contentRevision":7},"headers":[],"relativePath":"en/players/live.md","filePath":"en/players/live.md"}'),o={name:"en/players/live.md"};function n(l,e,h,d,p,u){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="live-the-active-map" tabindex="-1">Live: the active map <a class="header-anchor" href="#live-the-active-map" aria-label="Permalink to &quot;Live: the active map&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><img class="wiki-art" src="'+t+'" alt="The owner simulates the map; the guest sends orders and receives updates." width="960" height="440"><p class="wiki-caption">The owner simulates the map; the guest sends orders and receives updates.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>The guest proposes a live raid or visit with selected pawns. The host accepts the invitation (60 seconds by default). Once loaded, the guest sees a map mirror; commands execute on the host, who remains authoritative for simulation and saving.</p><p>The slower requested speed wins. The guest has a separate pause budget (10 pauses of 60 seconds by default). Letter-triggered pauses use the stricter participant preference. The guest can leave; the host can abort.</p><p>After losing connection, wait for PeerBack/reconnection. Retries continue every 60 seconds; after two minutes the game offers the menu. Desynchronization calls for a fresh snapshot, not manual map editing.</p><h2 id="live-flow" tabindex="-1">Live session: guest and host actions <a class="header-anchor" href="#live-flow" aria-label="Permalink to &quot;Live session: guest and host actions {#live-flow}&quot;">​</a></h2><ol><li>The guest launches a live raid/visit by caravan or pods. The host must be online at home.</li><li>The host has one minute to answer. Refused/timed-out raids continue as ordinary raids with the chosen timing; live-visit pawns return by mail.</li><li>The guest saves home and loads a mirror. The host pauses until the mirror is ready.</li><li>The guest controls <strong>their own</strong> pawns, work and schedules. Orders execute on the host; other objects are view-only.</li><li>Watch the upper-right overlay for state, tick and pauses. The slower requested speed wins; H/G mark each preference.</li><li>The guest uses <strong>End session</strong>, the host <strong>Abort session</strong>. Returned pawns and permitted loot come from the server outcome, not a copied mirror save.</li></ol><p>An outpost worker controlled by the host during a visit remains a mirror of the guest’s pawn. A protected return uses the original worker UUID and the server receipt.</p><p>The home save written before loading the mirror includes the UUID registry and protected receipts, even when the live session has already started. If that registry is ambiguous, mirror loading stops before the home save is written.</p><p>The host ends when all guest pawns are dead, captured or gone. A living downed/carried pawn may still keep the session active.</p><h2 id="live-failure" tabindex="-1">Pauses, mirror lag and disconnection <a class="header-anchor" href="#live-failure" aria-label="Permalink to &quot;Pauses, mirror lag and disconnection {#live-failure}&quot;">​</a></h2><p>The default guest budget is ten pauses of up to a minute. The host does not spend it. Letter pauses use the stricter Never/Major/Any threat preference, consume no guest budget, and clear when a speed is selected. This replaces vanilla automatic letter pauses during the session.</p><p>A lagging mirror requests a fresh snapshot; do not manually edit maps into agreement. If a peer drops, the other waits several minutes. After expiry, a lost raider is handed to host AI; a lost host reports completion when their game next logs in. Returns can therefore be delayed: do not spawn replacement pawns.</p><p>Coop uses a similar mirror, but assigned pawns belong to the host and are never guest mail escrow.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The host must stay online. Live does not create an independent second save. Do not end a session by deleting journals or manually granting pawns.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./coop">Persistent shared colony</a></li><li><a href="./raids-incidents">Raids and paid incidents</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li></ul>',21)])])}const v=a(o,[["render",n]]);export{g as __pageData,v as default};
